            // Setup touch handlers for zoom overlay
            const zoomOverlay = document.getElementById('gallery-trip-overlay');
            if (zoomOverlay) {
                // Prevent default click close on swipe
                let swiping = false;
                let touchStartX = 0;
                let touchStartY = 0;

                zoomOverlay.addEventListener('touchstart', function(e) {
                    swiping = false;
                    touchStartX = e.changedTouches[0].screenX;
                    touchStartY = e.changedTouches[0].screenY;
                }, { passive: true });

                zoomOverlay.addEventListener('touchend', function(e) {
                    const touchEndX = e.changedTouches[0].screenX;
                    const touchEndY = e.changedTouches[0].screenY;
                    const deltaX = touchEndX - touchStartX;
                    const deltaY = touchEndY - touchStartY;

                    // If it was a swipe, don't close the overlay
                    if (Math.abs(deltaX) > 50 || Math.abs(deltaY) > 50) {
                        swiping = true;
                        e.stopPropagation();
                    }
                }, { passive: true });

                // Override the onclick to check for swipes and counter clicks
                zoomOverlay.onclick = function(e) {
                    // Don't close if clicking on the counter div or its children (except close button)
                    const counter = document.getElementById('gallery-trip-counter');
                    if (counter && counter.contains(e.target) && e.target.id !== 'gallery-trip-close') {
                        return;
                    }

                    if (!swiping && (e.target === zoomOverlay || e.target.id === 'gallery-trip-close')) {
                        closeZoom('gallery-trip');
                    }
                    swiping = false;
                };

                // Setup swipe handlers for the overlay
                setupTouchHandlers(zoomOverlay, 'gallery-trip');
